import ifcopenshell
model = ifcopenshell.open("15_model/DC2-A-STR_Roof_Structure_Model_RevC.ifc")

for elem in model.by_type("IfcBuildingElementProxy"):
    name = elem.Name
    # Get placement
    if elem.ObjectPlacement:
        place = elem.ObjectPlacement.RelativePlacement
        if place:
            loc = place.Location
            if loc:
                x, y, z = loc.Coordinates
                print(f"{name}: x={x:.2f}, y={y:.2f}, z={z:.2f}")
    # Get height from representation
    if elem.Representation:
        for rep in elem.Representation.Representations:
            for item in rep.Items:
                if hasattr(item, 'Depth'):
                    print(f"  Depth: {item.Depth}")
                if hasattr(item, 'Height'):
                    print(f"  Height: {item.Height}")
                if hasattr(item, 'XDim'):
                    print(f"  XDim: {item.XDim}, YDim: {item.YDim}, ZDim: {item.ZDim}")
